// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
//
// `.env.local` is loaded before `.env`, because that is the file this project
// documents and the one Next.js itself reads (see .env.example). Bare
// `dotenv/config` only looks at `.env`, so `prisma migrate deploy` failed with
// "datasource.url is required" on a checkout that had followed the README —
// the URL was there, in the file Prisma was not reading.
//
// `override: false` is the default and is what makes the order meaningful:
// the first file to define a variable wins, and a real environment variable
// set by the shell or the host still beats both.
import { config as loadEnv } from "dotenv";
loadEnv({ path: ".env.local" });
loadEnv();

import { defineConfig } from "prisma/config";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: process.env["DATABASE_URL"],
  },
});
